import React, { useState } from "react";
import Tree from "react-d3-tree";

export default function TextInputDisplay() {
  const [text, setText] = useState("");
  const [fileContent, setFileContent] = useState("");
  const [file, setFile] = useState(null);
  const [output, setOutput] = useState([]);
  const [acciones, setAcciones] = useState([]);
  const [tablaSimbolos, setTablaSimbolos] = useState([]);
  const [arbol, setArbol] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleTextChange = (e) => {
    setText(e.target.value);
    if (e.target.value) {
      setFile(null);
      setFileContent("");
    }
  };

  const handleFileChange = async (event) => {
    if (event.target.files.length > 0) {
      const selectedFile = event.target.files[0];
      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target.result;
        setFileContent(content);
        setText("");
      };
      reader.readAsText(selectedFile);
      setFile(selectedFile);
    }
  };

  const formatToken = (token) => {
    const typeMap = {
      NUMERO: "num",
      IDENTIFICADOR: "id",
      OPERADOR: "op",
      OPERADOR_COMPARACION: "op_comp",
      OPERADOR_LOGICO: "op_log",
      AGRUPADOR: "agrup",
      PUNTO_Y_COMA: "ptcoma",
      TIPO_DATO: "tipo",
      PALABRA_RESERVADA: "palres",
      FUNCION_RESERVADA: "func",
      BOOLEANO: "bool",
      CHAR: "char",
      LITERAL: "lit",
      ERROR: "error",
    };

    const tipo = token.tipo || "error";
    const valor = token.valor || "?";
    return `<${typeMap[tipo] || tipo.toLowerCase()},${valor}>`;
  };

  const convertirArbol = (texto) => {
    const tokens = texto.match(/\w+|\(|\)/g);
    let i = 0;

    const parseNode = () => {
      const name = tokens[i++];
      const children = [];

      while (tokens[i] === "(") {
        i++;
        children.push(parseNode());
        i++;
      }

      return children.length
        ? { name, children }
        : { name };
    };

    return parseNode();
  };

  const handleAnalyze = async () => {
    const contentToAnalyze = fileContent || text;

    if (!contentToAnalyze.trim()) {
      setError("Por favor, ingresa un código fuente o carga un archivo.");
      return;
    }

    setLoading(true);
    setError("");
    setOutput([]);
    setAcciones([]);
    setTablaSimbolos([]);
    setArbol(null);

    try {
      const response = await fetch("http://localhost:8081/api/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: contentToAnalyze }),
      });

      const data = await response.json();

      if (!response.ok) {
        if (data.errores?.length > 0) {
          const erroresStr = data.errores
            .map((e) => `Línea ${e.linea}, Columna ${e.columna}: ${e.mensaje}`)
            .join("\n");
          setError(erroresStr);
        } else {
          setError(data.message || "Error al analizar el código");
        }
        return;
      }

      const tokens = data.tokens || [];
      setOutput(tokens);
      setAcciones(data.acciones || []);
      setArbol(data.arbol ? convertirArbol(data.arbol) : null);

      // Generar tabla de símbolos
      const vistos = new Set();
      const simbolos = [];
      let pos = 1;
      for (const token of tokens) {
        if (token.tipo === "IDENTIFICADOR" && !vistos.has(token.valor)) {
          simbolos.push({ posicion: pos++, ...token });
          vistos.add(token.valor);
        }
      }
      setTablaSimbolos(simbolos);
    } catch (err) {
      setError(`Error de conexión: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h2>Analizador Léxico y Sintáctico</h2>
      <textarea
        value={text}
        onChange={handleTextChange}
        rows={6}
        placeholder="Ingresa el código aquí"
        style={{ width: "100%", marginBottom: "10px" }}
        disabled={!!file}
      />
      <input type="file" onChange={handleFileChange} disabled={text !== ""} />
      <button onClick={handleAnalyze} style={{ marginTop: "10px" }}>
        {loading ? "Analizando..." : "Analizar"}
      </button>

      {error && <pre style={{ color: "red" }}>{error}</pre>}

      {output.length > 0 && (
        <>
          <h3>Tokens Generados</h3>
          <pre style={{ background: "#eee", padding: "10px" }}>
            {output.map((t, i) => (
              <span key={i}>{formatToken(t)} </span>
            ))}
          </pre>

          <table border="1" cellPadding="5" style={{ marginTop: "10px" }}>
            <thead>
              <tr>
                <th>Tipo</th>
                <th>Valor</th>
                <th>Línea</th>
                <th>Columna</th>
              </tr>
            </thead>
            <tbody>
              {output.map((t, i) => (
                <tr key={i}>
                  <td>{t.tipo}</td>
                  <td>{t.valor}</td>
                  <td>{t.linea}</td>
                  <td>{t.columna}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}

      {tablaSimbolos.length > 0 && (
        <>
          <h3>Tabla de Símbolos</h3>
          <table border="1" cellPadding="5">
            <thead>
              <tr>
                <th>Posición</th>
                <th>Identificador</th>
                <th>Tipo de Token</th>
                <th>Línea</th>
                <th>Columna</th>
              </tr>
            </thead>
            <tbody>
              {tablaSimbolos.map((t, i) => (
                <tr key={i}>
                  <td>{t.posicion}</td>
                  <td>{t.valor}</td>
                  <td>{t.tipo}</td>
                  <td>{t.linea}</td>
                  <td>{t.columna}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}

      {acciones.length > 0 && (
        <>
          <h3>Acciones Semánticas</h3>
          <ul>
            {acciones.map((a, i) => (
              <li key={i}>{a}</li>
            ))}
          </ul>
        </>
      )}

      {arbol && (
        <>
          <h3>Árbol de Derivación</h3>
          <div style={{ width: "100%", height: "500px" }}>
            <Tree data={arbol} orientation="vertical" />
          </div>
        </>
      )}
    </div>
  );
}
